        r, c = q.popleft()
        for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            nr, nc = r + dr, c + dc
            if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] == 0 and not outside[nr][nc]:
                outside[nr][nc] = True
                q.append((nr, nc))

    result = [row[:] for row in grid]
